<template>  <div class="file-path">文件路径：{{ filePath }}</div>  <n-divider/>  <div class="ocr-container">    <div class="ocr-text-container">      <n-input v-model:value="imageText"               type="textarea"               rows="5"               class="ocr-text"      >        <template #suffix>          <font-awesome-icon :icon="faCopy" class="copy-icon" @click="copyText"/>        </template>      </n-input>    </div>    <n-divider/>    <img        :src="convertFileSrc(filePath)"        width="100%"        alt="图片加载失败"        class="ocr-img"/>  </div></template><script setup lang="ts">import {onMounted, onUnmounted, ref} from "vue";import {convertFileSrc, invoke} from "@tauri-apps/api/core";import {listen} from "@tauri-apps/api/event";import {NDivider, NInput, useMessage} from 'naive-ui';import {faCopy} from "@fortawesome/free-regular-svg-icons";const message = useMessage();const filePath = ref('');const imageText = ref('');/** * 初始化文件更新监听器 */let reloadFilePathListener: any = null;async function initReloadFilePathListener() {  return await listen('reload-ocr-preview', async (event: any) => {    console.log("加载新的ocr图片", event.payload);    const itemId = event.payload.itemId;    if (itemId) {      // @ts-ignore      filePath.value = await window.getItemFilePath(itemId);    }    // 更新窗口url    window.history.replaceState(null, '', `${window.location.origin}${window.location.pathname}?pluginId=ocr&itemId=${itemId}`);    await loadImageText();  });}/** * 加载图片文字 */async function loadImageText() {  const result = await invoke("invoke_external_plugin", {    pluginId: "ocr",    pluginName: "ocr_plugin.exe",    cmd: "ocr",    payload: JSON.stringify({filePath: filePath.value})  }) as string;  console.log("图片识别结果：", result);  if (result && result.includes("result")) {    const json = JSON.parse(result);    if (json.result) {      imageText.value = json.result;      return;    }  }  imageText.value = "图片识别失败";}async function copyText() {  await invoke("write_to_clipboard", {content: imageText.value, format: 'text'});  message.success("已复制到剪贴板");}onMounted(async () => {  const searchParams = new URLSearchParams(window.location.search);  const itemId = <string>searchParams.get('itemId');  if (itemId) {    // @ts-ignore    filePath.value = await window.getItemFilePath(itemId);  }  console.log("OCR图片路径：", filePath.value)  // 初始化文件更新监听器  reloadFilePathListener = await initReloadFilePathListener();  await loadImageText();})onUnmounted(() => {  // 销毁文件更新监听器  if (reloadFilePathListener) {    reloadFilePathListener();  }})</script><style>.file-path {  padding: 5px;}.ocr-container {  width: 100%;  height: 100%;}.ocr-text-container {  padding: 2%;}.copy-icon {  width: 20px;  height: 20px;  fill: var(--theme-universal-text) !important;  opacity: 0.6;  margin-bottom: 5px;  cursor: pointer;}.copy-icon:hover {  opacity: 0.8;}.ocr-img {  object-fit: cover;  margin: 2%;  width: 96%;  overflow: auto;}</style>